def find_rectangular_frames(grid, target_color):
    """Find rectangular frames of a given color with empty interiors"""
    frames = []
    h, w = len(grid), len(grid[0])

    # Look for horizontal lines of target_color with length >= 3
    horizontal_signatures = {}

    for row_idx in range(h):
        for col_idx in range(w):
            if grid[row_idx][col_idx] == target_color:
                # Count consecutive same color to the right
                if (row_idx, col_idx) not in horizontal_signatures:
                    count = 1
                    col_idx_2 = col_idx + 1
                    while col_idx_2 < w and grid[row_idx][col_idx_2] == target_color:
                        count += 1
                        col_idx_2 += 1
                    horizontal_signatures[(row_idx, col_idx)] = count
                    col_idx = col_idx_2 - 1  # Skip since we've counted
                else:
                    count = horizontal_signatures[(row_idx, col_idx)]
                    col_idx += count  # Skip

    # Group into connected components that look like frames
    visited = set()
    frames = []

    for start_row in range(h):
        for start_col in range(w):
            if grid[start_row][start_col] == target_color and (start_row, start_col) not in visited:
                # BFS to find connected region
                component = []
                queue = [(start_row, start_col)]
                visited.add((start_row, start_col))

                while queue:
                    r, c = queue.pop()
                    component.append((r, c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

                # Check if component looks like a frame (rectangular with hole)
                if len(component) >= 8:  # Minimum frame size
                    rows = [r for r, c in component]
                    cols = [c for r, c in component]
                    min_r, max_r = min(rows), max(rows)
                    min_c, max_c = min(cols), max(cols)

                    # Check if it forms a frame (perimeter filled, interior empty)
                    frame = True
                    for r in range(min_r, max_r+1):
                        for c in range(min_c, max_c+1):
                            if (r, c) in component:
                                if not ((r == min_r or r == max_r) or (c == min_c or c == max_c)):
                                    frame = False
                            elif not ((r == min_r or r == max_r) or (c == min_c or c == max_c)):
                                # Interior cell is not part of frame
                                pass

                    if frame:
                        frames.append({
                            'color': target_color,
                            'top': min_r,
                            'left': min_c,
                            'bottom': max_r,
                            'right': max_c,
                            'cells': component
                        })

    return frames

