def find_all_frames(grid):
    """Find all frames - rim filled, interior empty"""
    h, w = len(grid), len(grid[0])
    visited = set()
    frames = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4 and (r, c) not in visited:
                color = grid[r][c]

                # BFS to collect all cells
                color_cells = set()
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in color_cells:
                        continue
                    color_cells.add((cr, cc))
                    visited.add((cr, cc))
                    for nr, nc in [(cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1)]:
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and (nr, nc) not in color_cells:
                                color_cells.add((nr, nc))
                                queue.append((nr, nc))

                # Check if proper frame (rim of color, interior different)
                top = min(cr for cr, cc in color_cells)
                bottom = max(cr for cr, cc in color_cells)
                left = min(cc for cr, cc in color_cells)
                right = max(cc for cr, cc in color_cells)

                is_frame = True
                zero_count = 0
                for cr in range(top, bottom + 1):
                    for cc in range(left, right + 1):
                        if (cr, cc) in color_cells:
                            if not ((cr == top or cr == bottom) or (cc == left or cc == right)):
                                # Interior cell with color - not a frame
                                is_frame = False
                                zero_count += 1
                        elif 0 <= cc < w:
                            zero_count += 1

                # Check if interior is not filled with same color
                if is_frame:
                    # Count interior cells - should be empty of color
                    for cr in range(top+1, bottom):
                        for cc in range(left+1, right):
                            if (cr, cc) in color_cells:
                                is_frame = False

                    if is_frame:
                        frames.append({
                            'color': color,
                            'top': top, 'bottom': bottom,
                            'left': left, 'right': right
                        })

    return frames

