    for color in [5, 6, 9]:
        for r1 in range(h):
            for c1 in range(w):
                if grid[r1][c1] == color:
                    # Get all cells of this color connected to (r1, c1)
                    cells = set()
                    queue = [(r1, c1)]
                    while queue:
                        cr, cc = queue.pop(0)
                        if (cr, cc) in cells or grid[cr][cc] != color:
